/* Example for a variable font supporting 'wght' (weight) and 'wdth' (width) axes */
.hero-title {
    font-family: 'Inter Variable', sans-serif;
    font-variation-settings: "wght" 700, "wdth" 120; /* Weight 700 and width 120 */
    font-size: 3rem;
    line-height: 1.1;
}

.call-to-action {
    font-family: 'Inter Variable', sans-serif;
    font-variation-settings: "wght" 600, "wdth" 90; /* Weight 600 and width 90 */
    font-size: 1.25rem;
    letter-spacing: -0.02em;
}

/* Example with a custom axis for grade (GRAD), if supported by the font */
.subtle-text {
    font-family: 'Custom Var Font', serif;
    font-variation-settings: "wght" 400, "GRAD" 50; /* Normal weight, grade 50 */
    font-size: 0.9rem;
    color: #555;
}
